{
  "decision-post-deposit-after-phased-acceptance": "WITH daily AS (SELECT order_id, date(accepted_on) AS day, SUM(CASE WHEN phase = 'fit' THEN units ELSE 0 END) AS fit_units, SUM(CASE WHEN phase = 'finish' THEN units ELSE 0 END) AS finish_units FROM acceptance GROUP BY order_id, date(accepted_on)), milestones AS (SELECT order_id, day, SUM(fit_units) OVER w AS fit_total, SUM(finish_units) OVER w AS finish_total FROM daily WINDOW w AS (PARTITION BY order_id ORDER BY day ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), postings AS (SELECT order_id, MIN(day) AS posting_date FROM milestones WHERE fit_total >= 3 AND finish_total >= 2 GROUP BY order_id) SELECT p.order_id, p.posting_date, k.deposit_cents AS deposit_credit_cents FROM postings AS p JOIN kit_orders AS k ON k.order_id = p.order_id ORDER BY p.posting_date, p.order_id",
  "decision-prepaid-booth-space-close": "WITH bookings AS (SELECT DISTINCT booking_code FROM booth_change), corrected AS (SELECT b.booking_code, (SELECT c.fee_cents FROM booth_change AS c WHERE c.booking_code = b.booking_code AND c.fee_cents IS NOT NULL ORDER BY c.rev_no DESC LIMIT 1) AS fee, (SELECT c.first_month FROM booth_change AS c WHERE c.booking_code = b.booking_code AND c.first_month IS NOT NULL ORDER BY c.rev_no DESC LIMIT 1) AS start_month, (SELECT c.span_months FROM booth_change AS c WHERE c.booking_code = b.booking_code AND c.span_months IS NOT NULL ORDER BY c.rev_no DESC LIMIT 1) AS span FROM bookings AS b), recognized AS (SELECT booking_code, fee, CASE WHEN start_month > 6 THEN 0 WHEN 7 - start_month >= span THEN fee ELSE (fee / span) * (7 - start_month) END AS expense_to_date_cents FROM corrected) SELECT booking_code, expense_to_date_cents, fee - expense_to_date_cents AS prepaid_cents FROM recognized ORDER BY booking_code",
  "decision-prepaid-rental-expense-export": "WITH expenses AS (SELECT b.bay, b.plan_cents, COALESCE(SUM((r.fee_cents / (r.stop_day - r.start_day)) * MAX(0, MIN(r.stop_day, 61) - MAX(r.start_day, 31))), 0) AS expense_cents FROM bay_budget AS b LEFT JOIN prepaid_rental AS r ON r.bay = b.bay GROUP BY b.bay, b.plan_cents) SELECT 'bay,expense_cents,variance_cents' || char(10) || COALESCE((SELECT group_concat(line, '') FROM (SELECT bay || ',' || expense_cents || ',' || (expense_cents - plan_cents) || char(10) AS line FROM expenses ORDER BY bay COLLATE BINARY)), '') AS csv_text",
  "decision-preserve-a-reusable-reel-remnant": "WITH assignments AS (SELECT a.reel_code AS run_one_reel, b.reel_code AS run_two_reel, c.reel_code AS run_three_reel FROM reel_stock AS a CROSS JOIN reel_stock AS b CROSS JOIN reel_stock AS c), remnants AS (SELECT a.run_one_reel, a.run_two_reel, a.run_three_reel, s.bulletin_id, r.available_m - SUM(CASE WHEN r.reel_code = (CASE k.run_no WHEN 1 THEN a.run_one_reel WHEN 2 THEN a.run_two_reel WHEN 3 THEN a.run_three_reel END) THEN k.finished_m + s.allowance_m ELSE 0 END) AS remaining_m FROM assignments AS a CROSS JOIN reel_stock AS r CROSS JOIN cut_list AS k CROSS JOIN shop_bulletin AS s GROUP BY a.run_one_reel, a.run_two_reel, a.run_three_reel, s.bulletin_id, r.reel_code, r.available_m) SELECT run_one_reel, run_two_reel, run_three_reel, MAX(remaining_m) AS longest_remnant_m, bulletin_id FROM remnants GROUP BY run_one_reel, run_two_reel, run_three_reel, bulletin_id HAVING MIN(remaining_m) >= 0 ORDER BY longest_remnant_m DESC, run_one_reel COLLATE BINARY, run_two_reel COLLATE BINARY, run_three_reel COLLATE BINARY LIMIT 1"
}
